"""Measured shell for the owner's selected ARTEMIS interface reference."""

REFERENCE_CSS = r"""
html{background:#142D29}
body{background:#142D29;max-width:1008px;margin:0 auto;min-height:100vh;box-shadow:0 0 72px #0d201d55;font-size:12px}
body::before{content:none}
body>.topnav,body>main{background:#F7F6F1}
.topnav{min-height:49px;height:49px;padding:0 35px;gap:0;max-width:1008px;border-bottom:1px solid #deddd4}
.brand{gap:11px}.brand .mark{width:30px;height:30px}.brand .word{font-size:11px;font-weight:500;letter-spacing:.36em;padding-left:0}
.topnav nav.primary{display:flex;margin-left:50px;gap:27px;align-self:stretch}.topnav nav.primary a{font-size:9px;color:#5c615c;line-height:1;font-weight:500;border-bottom:0;position:relative}
.topnav nav.primary a.active{font-weight:700;border-bottom:0}.topnav nav.primary a.active::after{content:'';height:1px;position:absolute;bottom:8px;left:0;right:0;background:#142D29}
.nav-right{gap:19px}.ask-pill{border:0;background:none;box-shadow:none;width:24px;min-height:28px;padding:3px;justify-content:center}.ask-pill .ask-label{display:none}.ask-pill svg{width:14px;height:14px;stroke:#26312E}.ask-pill:hover{background:#E8E5DC}
.avatar{border-radius:50%;width:25px;min-width:25px;height:25px;min-height:25px;font-size:9px;font-weight:500;background:#343d34;border:0;box-shadow:none}
.bell{display:none}.navtoggle{display:none}.usermenu .menu{top:36px;font-size:12px}.usermenu .menu a{font-size:12px}
.wrap{max-width:none;margin:0;min-height:calc(100vh - 49px);padding:30px 38px 48px}.wrap h1{font-size:32px;line-height:1.12;margin:0 0 5px;font-weight:500}.wrap>p{font-size:11px;line-height:1.55}.wrap h2{font-size:20px}.wrap h3{font-family:'Artemis Sans',sans-serif;font-size:12px}.wrap .card{padding:19px 20px;border-color:#e7e4da;background:#faf9f4;border-radius:4px;box-shadow:none}.wrap .btn,.wrap button{font-size:11px;min-height:33px;border-radius:4px;padding:8px 15px;background:#142D29;border-color:#142D29}.wrap button.secondary{background:transparent;color:#26312E;border-color:#d5d6cc}.wrap input,.wrap select,.wrap textarea{font-size:12px;min-height:34px}.wrap label{font-size:11px}.pill{font-size:9px;padding:2px 7px;border:0;border-radius:4px}.line{font-size:11px}.muted{color:#687068}
.wrap .studio-nav button img{vertical-align:middle;opacity:.75;margin-right:8px;flex:none}.wrap .studio-nav button{background:transparent;color:#687068;border:0;font-size:11px;font-weight:500;min-height:29px;padding:7px 10px}.wrap .studio-nav button[aria-current=true]{background:#E8E9E1;color:#142D29;font-weight:600}.wrap .studio-nav button:hover{background:#E8E9E1;color:#142D29}
.reference-tabs{display:flex;gap:25px;align-items:center;border-bottom:1px solid #deddd4;margin:16px 0 20px}.reference-tabs button{position:relative;border:0;border-radius:0;background:none;color:#62695f;padding:8px 0 10px;min-height:30px;font-size:10px;font-weight:500}.reference-tabs button[aria-selected=true]{color:#142D29;font-weight:700}.reference-tabs button[aria-selected=true]::after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:1px;background:#142D29}.reference-tabs button:hover{background:none;color:#142D29}
.career-overview{display:grid;grid-template-columns:1fr 1.25fr;gap:20px}.career-overview .card{margin:0}.target-roles{list-style:none;padding:0;margin:0}.target-roles li{padding:13px 0;border-top:1px solid #e8e6dc;display:flex;justify-content:space-between;gap:10px;font-size:11px;font-weight:600}.target-roles li:first-child{border-top:0}.career-pref{display:flex;gap:13px;align-items:flex-start;margin:18px 0}.career-pref img{width:17px;height:17px;flex:none}.career-pref strong{display:block;font-size:11px;font-weight:600}.career-pref small{display:block;font-size:9px;color:#687068}.career-overview .card h2{font-family:'Artemis Sans',sans-serif;font-size:12px;font-weight:700;margin-bottom:6px}.career-overview .card h3{font-size:11px}.career-facts{margin:0;padding-left:18px}.career-facts li{padding:6px 0}.career-empty{padding:18px 0}.career-note{font-size:10px;color:#687068}.career-overview .pill{background:#e5ece1;font-weight:500}.plan-more{margin-top:24px}.wrap [role=tabpanel][hidden]{display:none}.reference-tabs:focus-within{outline:none}
@media(max-width:1050px){body{max-width:1008px}.topnav{padding-left:24px;padding-right:24px}.topnav nav.primary{margin-left:40px;gap:22px}}
@media(max-width:760px){body{width:100%;box-shadow:none;background:#F7F6F1}.topnav{height:55px;min-height:55px;padding:0 20px;gap:0}.brand{gap:9px}.brand .mark{width:25px;height:30px}.brand .word{font-size:10px;letter-spacing:.30em}.topnav nav.primary{display:none}.nav-right{gap:12px}.ask-pill,.usermenu{display:none}.navtoggle{display:block}.navtoggle summary{font-size:0;border:0;padding:8px 0;min-width:22px}.navtoggle summary img{display:block;width:18px;height:18px}.navtoggle .mobilemenu{right:0;top:35px;min-width:190px}.wrap{padding:25px 20px 38px;min-height:calc(100vh - 55px)}.wrap h1{font-size:29px}.reference-tabs{gap:21px;overflow-x:auto;white-space:nowrap;margin-top:16px}.reference-tabs button{flex:none}.career-overview{grid-template-columns:1fr;gap:14px}.wrap .card{padding:17px}.career-pref{margin:15px 0}.career-pref strong{font-size:12px}.career-pref small{font-size:10px}}
@media(max-width:760px){.topnav{height:75px;min-height:75px;padding:0 29px}.brand{gap:16px}.brand .mark{width:46px;height:50px}.brand .word{font-size:16px;letter-spacing:.5em}.navtoggle summary{min-width:28px}.navtoggle summary img{width:28px;height:28px}.wrap{min-height:calc(100vh - 75px)}}

@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
"""
